import os
import torch


class Config:
    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    # Root directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Specific directory for this solution (Idea 58)
    # This is where cached features and model checkpoints will be stored
    IDEA_DIR = os.path.join(WORKING_DIR, "idea_58")

    # Metadata Input Files (Generated by metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Cache Files (Parquet/NPY) for deterministic loading
    CACHE_TRAIN_PROCESSED = os.path.join(IDEA_DIR, "train_processed.parquet")
    CACHE_VAL_PROCESSED = os.path.join(IDEA_DIR, "val_processed.parquet")
    CACHE_TEST_PROCESSED = os.path.join(IDEA_DIR, "test_processed.parquet")

    # Feature Caches (Optional separation if needed by pipeline)
    CACHE_SBERT_EMBEDDINGS = os.path.join(IDEA_DIR, "sbert_embeddings.npz")
    CACHE_TFIDF_VECTORS = os.path.join(IDEA_DIR, "tfidf_vectors.npz")

    # Model Artifacts
    MODEL_MLP_PATH = os.path.join(IDEA_DIR, "best_mlp.pth")
    MODEL_RF_PATH = os.path.join(IDEA_DIR, "best_rf.pkl")

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Reproducibility
    # --------------------------------------------------------------------------
    RANDOM_SEED = 42

    # --------------------------------------------------------------------------
    # Data Configuration
    # --------------------------------------------------------------------------
    TARGET_COL = "requester_received_pizza"
    ID_COL = "request_id"

    # Text Columns
    TEXT_TITLE_COL = "request_title"
    TEXT_BODY_COL = "request_text_edit_aware"  # Use edit aware version to avoid leakage

    # Columns to Drop (Leakage, Identifiers, or Raw Text)
    DROP_COLS = [
        "giver_username_if_known",  # Leakage: Target info
        "request_id",  # Identifier
        "source_file",  # Metadata artifact
        "request_text",  # Raw text (we use edit_aware)
        "requester_username",  # High cardinality, potential bias
        "requester_subreddits_at_request",  # List format, handled via feature eng
        "post_was_edited",  # Potential leakage
        "unix_timestamp_of_request",  # Redundant/Correlated
        "unix_timestamp_of_request_utc",  # Redundant/Correlated
    ]

    # --------------------------------------------------------------------------
    # Feature Engineering Hyperparameters
    # --------------------------------------------------------------------------
    # SBERT (Semantic Features)
    SBERT_MODEL_NAME = "all-MiniLM-L6-v2"
    SBERT_EMBEDDING_DIM = 384

    # TF-IDF (Lexical Features for RF)
    TFIDF_MAX_FEATURES = 5000
    TFIDF_NGRAM_RANGE = (1, 2)

    # Community Features
    TOP_K_SUBREDDITS = 50

    # --------------------------------------------------------------------------
    # Model Hyperparameters: Random Forest (Stream A)
    # --------------------------------------------------------------------------
    # "Multi-Interaction Trees" settings
    RF_N_ESTIMATORS = 500
    RF_MAX_DEPTH = None  # Allow deep trees for interaction capture
    RF_MIN_SAMPLES_LEAF = 1  # Low regularization
    RF_CLASS_WEIGHT = "balanced"
    RF_N_JOBS = -1  # Use all cores

    # --------------------------------------------------------------------------
    # Model Hyperparameters: MLP (Stream B)
    # --------------------------------------------------------------------------
    # "Decoupled Orthogonal Skip-Gated MLP" settings

    # Architecture Dimensions
    MLP_TOPIC_HIDDEN_DIM = 256  # Stream 1 (Topic)
    MLP_NARRATIVE_HIDDEN_DIM = 256  # Stream 2 (Narrative)
    MLP_GATE_HIDDEN_DIM = 64  # Gating Network
    MLP_FINAL_HIDDEN_DIM = 128  # Fusion Layer

    # Regularization
    MLP_DROPOUT_EMB = 0.5  # High dropout on embeddings
    MLP_DROPOUT_DENSE = 0.2  # Moderate dropout on dense layers

    # Optimization
    MLP_LEARNING_RATE = 1e-4
    MLP_WEIGHT_DECAY = 1e-4
    MLP_BATCH_SIZE = 64
    MLP_EPOCHS = 50
    MLP_PATIENCE = 15  # High patience as per strategy

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # --------------------------------------------------------------------------
    # Ensemble
    # --------------------------------------------------------------------------
    ENSEMBLE_WEIGHT_RF = 0.5
    ENSEMBLE_WEIGHT_MLP = 0.5

    # --------------------------------------------------------------------------
    # Utilities
    # --------------------------------------------------------------------------
    @classmethod
    def create_directories(cls):
        """Creates necessary directories for caching and outputs."""
        os.makedirs(cls.IDEA_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        print(f"Directories created: {cls.IDEA_DIR}, {cls.SUBMISSION_DIR}")
